// Paper Texture preset generated by the 21st.dev Shader Builder.
// Adapted from Paper Shaders (Apache-2.0), https://shaders.paper.design/paper-texture.

export const PAPER_VERTEX_SHADER = `
  attribute vec2 a_position;

  void main() {
    gl_Position = vec4(a_position, 0.0, 1.0);
  }
`;

export const PAPER_FRAGMENT_SHADER = `
  #ifdef GL_FRAGMENT_PRECISION_HIGH
  precision highp float;
  #else
  precision mediump float;
  #endif

  uniform vec2 u_resolution;
  uniform vec3 u_dark;
  uniform vec3 u_light;

  float hash21(vec2 cell) {
    #ifndef GL_FRAGMENT_PRECISION_HIGH
    cell = mod(cell, 31.0);
    #endif
    cell = fract(cell * vec2(234.34, 435.345));
    cell += dot(cell, cell + 34.23);
    return fract(cell.x * cell.y);
  }

  // Dave Hoskins' hash12 for the final fine grain.
  float grainHash(vec2 pixel) {
    vec3 point = fract(pixel.xyx * 0.1031);
    point += dot(point, point.yzx + 33.33);
    return fract((point.x + point.y) * point.z);
  }

  float valueNoise(vec2 point) {
    vec2 cell = floor(point);
    vec2 weight = fract(point);
    weight = weight * weight * (3.0 - 2.0 * weight);
    return mix(
      mix(hash21(cell), hash21(cell + vec2(1.0, 0.0)), weight.x),
      mix(hash21(cell + vec2(0.0, 1.0)), hash21(cell + vec2(1.0, 1.0)), weight.x),
      weight.y
    );
  }

  float layeredNoise(vec2 point) {
    float value = 0.0;
    float amplitude = 0.5;
    for (int octave = 0; octave < 5; octave++) {
      value += amplitude * valueNoise(point);
      point = point * 2.03 + vec2(17.0, 9.2);
      amplitude *= 0.5;
    }
    return value;
  }

  void main() {
    float shortSide = max(min(u_resolution.x, u_resolution.y), 1.0);
    vec2 point = (gl_FragCoord.xy - 0.5 * u_resolution) / shortSide;
    vec2 paper = point * 1.26;

    float column = floor(point.x * 199.0);
    float stagger = hash21(vec2(column, 3.0));
    float row = floor(point.y * 47.76 + stagger);
    float fibers = hash21(vec2(column, row) + 1.0);
    float fineFibers = hash21(floor(point * 537.3) + 2.3);
    float crumples = layeredNoise(paper * 3.575 + 1.0);

    // Light and shadow on opposite sides of each fold keep the relief balanced.
    vec2 crease = paper + vec2(0.17, -0.12);
    float angle = atan(crease.y, crease.x + 0.0001);
    float fold = angle * 5.0 + crumples * 2.2;
    float ridge = pow(abs(sin(fold)), 10.0);
    float shadow = pow(abs(sin(fold + 0.42)), 14.0);
    float foldFade = smoothstep(0.025, 0.15, length(crease));
    float relief = (ridge * 0.17 - shadow * 0.095) * foldFade;
    float flecks = smoothstep(0.82, 0.98, layeredNoise(paper * 9.0 + 8.4)) * 0.098;

    float texture = 0.43 + (crumples - 0.5) * 0.35 + (fibers - 0.5) * 0.27
      + (fineFibers - 0.5) * 0.12 + relief - flecks;
    float grain = (grainHash(gl_FragCoord.xy + vec2(17.0, 31.0)) - 0.5) * 0.042;
    vec3 color = mix(u_dark, u_light, smoothstep(0.0, 1.0, texture));
    gl_FragColor = vec4(clamp(color + grain, 0.0, 1.0), 1.0);
  }
`;
